package com.kuaixietech.commerce;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
class ProductInventoryTest {
 @Test void cancelledUnpurchasedStockIsRestoredOnlyOnce(){var db=mock(JdbcTemplate.class);var state=new HashMap<String,Object>(Map.of("product_id","product","quantity",2,"stock_state","held"));when(db.queryForList(startsWith("SELECT order_id"),any(Object[].class))).thenReturn(List.of(Map.of("order_id","order")));when(db.queryForList(startsWith("SELECT product_id"),any(Object[].class))).thenAnswer(c->List.of(new HashMap<>(state)));when(db.update(anyString(),any(Object[].class))).thenAnswer(c->{if(c.<String>getArgument(0).startsWith("UPDATE t_product_order_reservations"))state.put("stock_state",c.getArgument(1));return 1;});var inventory=new ProductInventory(db);inventory.transition("order","released");inventory.transition("order","released");verify(db,times(1)).update(startsWith("UPDATE t_products SET stock=stock+"),eq(2),eq("product"));}
 @Test void procurementConsumptionDoesNotDecrementStockAgainOrAutomaticallyRestockOnRefund(){var db=mock(JdbcTemplate.class);var state=new HashMap<String,Object>(Map.of("product_id","product","quantity",2,"stock_state","held"));when(db.queryForList(startsWith("SELECT order_id"),any(Object[].class))).thenReturn(List.of(Map.of("order_id","order")));when(db.queryForList(startsWith("SELECT product_id"),any(Object[].class))).thenAnswer(c->List.of(new HashMap<>(state)));when(db.update(anyString(),any(Object[].class))).thenAnswer(c->{state.put("stock_state",c.getArgument(1));return 1;});var inventory=new ProductInventory(db);inventory.transition("order","consumed");inventory.transition("order","released");verify(db,never()).update(startsWith("UPDATE t_products"),any(Object[].class));assertEquals("consumed",state.get("stock_state"));}
 @Test void legacyOrderDoesNotLockNonexistentReservationRange(){var db=mock(JdbcTemplate.class);new ProductInventory(db).transition("legacy","released");verify(db,times(1)).queryForList(anyString(),any(Object[].class));verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void restoreFailureCannotMarkReservationReleased(){var db=mock(JdbcTemplate.class);when(db.queryForList(startsWith("SELECT order_id"),any(Object[].class))).thenReturn(List.of(Map.of("order_id","order")));when(db.queryForList(startsWith("SELECT product_id"),any(Object[].class))).thenReturn(List.of(Map.of("product_id","product","quantity",2,"stock_state","held")));assertThrows(IllegalStateException.class,()->new ProductInventory(db).transition("order","released"));verify(db,never()).update(startsWith("UPDATE t_product_order_reservations"),any(Object[].class));}
 @Test void sharedProfileOrderingIsDeterministicAndDeduplicated(){var db=mock(JdbcTemplate.class);when(db.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("id","profile")));new OrderProfileLocks(db).lock("z-buyer","a-seller");var sequence=inOrder(db);sequence.verify(db).queryForList(anyString(),eq("a-seller"));sequence.verify(db).queryForList(anyString(),eq("z-buyer"));}
}
